package com.blitzbook.app;
import android.app.Activity;import android.content.Intent;import android.net.Uri;import android.os.Bundle;import android.webkit.*;import android.widget.ProgressBar;
public class MainActivity extends Activity{private WebView w;private ProgressBar p;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);w=findViewById(R.id.webView);p=findViewById(R.id.progressBar);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setLoadsImagesAutomatically(true);s.setUseWideViewPort(false);s.setLoadWithOverviewMode(false);s.setSupportZoom(false);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setAllowFileAccessFromFileURLs(true);s.setAllowUniversalAccessFromFileURLs(true);w.setWebChromeClient(new WebChromeClient(){public void onProgressChanged(WebView v,int n){p.setProgress(n);p.setVisibility(n>=100?android.view.View.GONE:android.view.View.VISIBLE);}});w.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if("file".equals(u.getScheme())||"https".equals(u.getScheme()))return false;try{startActivity(new Intent(Intent.ACTION_VIEW,u));return true;}catch(Exception e){return false;}}});if(b==null)w.loadUrl("file:///android_asset/index.html");else w.restoreState(b);}@Override public void onBackPressed(){w.evaluateJavascript("(function(){var d=document.querySelector('.detail');if(d){d.remove();return true}return false})()",r->{if("true".equals(r))return;if(w.canGoBack())w.goBack();else MainActivity.super.onBackPressed();});}@Override protected void onSaveInstanceState(Bundle o){w.saveState(o);super.onSaveInstanceState(o);}}